public class ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}

public ListNode reverseBetween(ListNode head, int left, int right) {
    if (head == null || left == right) {
        return head;
    }
    ListNode dummy = new ListNode(0, head);
    ListNode beforeLeft = dummy;
    for (int i = 0; i < left - 1; i++) {
        beforeLeft = beforeLeft.next;
    }
    ListNode subTail = beforeLeft.next; // old position left -> becomes the tail
    ListNode prev = null;
    ListNode curr = beforeLeft.next;
    for (int i = 0; i <= right - left; i++) {
        ListNode next = curr.next;
        curr.next = prev;
        prev = curr;
        curr = next;
    }
    beforeLeft.next = prev;   // prefix -> new head (old position right)
    subTail.next = curr;      // new tail -> suffix (node after right)
    return dummy.next;
}

public ListNode reverseBetween(ListNode head, int left, int right) {
    if (head == null || left == right) {
        return head;
    }
    ListNode dummy = new ListNode(0, head);
    ListNode prevLeft = dummy;
    for (int i = 0; i < left - 1; i++) {
        prevLeft = prevLeft.next;
    }
    ListNode curr = prevLeft.next; // stays put; later nodes move ahead of it
    for (int i = 0; i < right - left; i++) {
        ListNode nxt = curr.next;
        curr.next = nxt.next;        // detach nxt
        nxt.next = prevLeft.next;    // nxt points at current window head
        prevLeft.next = nxt;         // nxt becomes the new window head
    }
    return dummy.next;
}

